import{_ as r,c as l,o as i,a2 as a}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"カスタマイズ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/customize.md","filePath":"ja/guide/customize.md","lastUpdated":1793163976000}'),o={name:"ja/guide/customize.md"};function n(e,t,s,d,g,h){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="カスタマイズ" tabindex="-1">カスタマイズ <a class="header-anchor" href="#カスタマイズ" aria-label="Permalink to &quot;カスタマイズ&quot;">​</a></h1><p>アーカイブ管理の体験をカスタマイズして、NueZip を真に自分好みにしてください。このガイドでは、カスタマイズできるすべての項目を説明します。</p><h2 id="一般設定" tabindex="-1">一般設定 <a class="header-anchor" href="#一般設定" aria-label="Permalink to &quot;一般設定&quot;">​</a></h2><p><strong>NueZip → 設定</strong>（または <code>Cmd+,</code> を押す）を開くと、すべてのカスタマイズオプションにアクセスできます。</p><h3 id="外観" tabindex="-1">外観 <a class="header-anchor" href="#外観" aria-label="Permalink to &quot;外観&quot;">​</a></h3><ul><li><strong>テーマ</strong>: ライト、ダーク、またはシステム（macOS の外観に追従）から選択</li><li><strong>アイコンスタイル</strong>: モノクロまたはフルカラーのメニューバーアイコンを設定</li><li><strong>言語</strong>: 対応言語から選択（English、中文、日本語、한국어、など）</li></ul><h2 id="圧縮のデフォルト" tabindex="-1">圧縮のデフォルト <a class="header-anchor" href="#圧縮のデフォルト" aria-label="Permalink to &quot;圧縮のデフォルト&quot;">​</a></h2><p>お好みの圧縮デフォルトを設定します：</p><table tabindex="0"><thead><tr><th>設定</th><th>オプション</th><th>説明</th></tr></thead><tbody><tr><td><strong>デフォルトフォーマット</strong></td><td>ZIP、7z、TAR、GZIP、BZIP2、XZ</td><td>クイック圧縮用のアーカイブフォーマット</td></tr><tr><td><strong>圧縮レベル</strong></td><td>Store、Fast、Normal、Maximum、Ultra</td><td>速度と圧縮率のトレードオフ</td></tr><tr><td><strong>暗号化</strong></td><td>None、AES-128、AES-256</td><td>ZIP/7z アーカイブのデフォルト暗号化</td></tr><tr><td><strong>ボリュームサイズ</strong></td><td>カスタム（MB）</td><td>マルチボリュームアーカイブのデフォルト分割サイズ</td></tr></tbody></table><h3 id="設定例" tabindex="-1">設定例 <a class="header-anchor" href="#設定例" aria-label="Permalink to &quot;設定例&quot;">​</a></h3><p>日常的な使用の場合：</p><ul><li><strong>フォーマット</strong>: ZIP</li><li><strong>レベル</strong>: Normal</li><li><strong>暗号化</strong>: AES-256（機密ファイル用）</li><li><strong>ボリューム</strong>: オフ</li></ul><p>アーカイブ保存の場合：</p><ul><li><strong>フォーマット</strong>: 7-Zip</li><li><strong>レベル</strong>: Ultra</li><li><strong>暗号化</strong>: AES-256</li><li><strong>ボリューム</strong>: 4.7 GB（DVD に収めるため）</li></ul><h2 id="展開設定" tabindex="-1">展開設定 <a class="header-anchor" href="#展開設定" aria-label="Permalink to &quot;展開設定&quot;">​</a></h2><p>展開の動作をカスタマイズします：</p><ul><li><strong>デフォルトでサブフォルダに展開</strong>: 展開時に名前付きフォルダを自動作成する</li><li><strong>展開後にフォルダを開く</strong>: 展開された内容を Finder で表示する</li><li><strong>上書き動作</strong>: 確認する、常に上書きする、または既存ファイルをスキップする</li><li><strong>ファイルの日付を保持</strong>: アーカイブから元のタイムスタンプを保持する</li></ul><h2 id="finder-機能拡張" tabindex="-1">Finder 機能拡張 <a class="header-anchor" href="#finder-機能拡張" aria-label="Permalink to &quot;Finder 機能拡張&quot;">​</a></h2><p>Finder のコンテキストメニュー連携を管理します：</p><ul><li><strong>有効／無効</strong>: 右クリックメニューの項目をオンまたはオフにする</li><li><strong>クイックアクション</strong>: コンテキストメニューに表示するアクションを選択する <ul><li>ここに展開</li><li>フォルダに展開</li><li>ZIP に圧縮</li><li>オプションを指定して圧縮</li></ul></li></ul><p>これらの管理は以下で行います：<strong>システム設定 → プライバシーとセキュリティ → 機能拡張 → Finder 機能拡張</strong></p><h2 id="メニューバー-トレイ-アイコン" tabindex="-1">メニューバー（トレイ）アイコン <a class="header-anchor" href="#メニューバー-トレイ-アイコン" aria-label="Permalink to &quot;メニューバー（トレイ）アイコン&quot;">​</a></h2><p>メニューバーのドロップパネルをカスタマイズします：</p><ul><li><strong>メニューバーに表示</strong>: トレイアイコンを有効／無効にする</li><li><strong>パネルを自動的に閉じる</strong>: 展開後にドロップパネルを閉じる</li><li><strong>最近のアーカイブ</strong>: 表示する最近の項目の数</li><li><strong>閉じるときに終了</strong>: アプリがバックグラウンドに残るかどうか</li></ul><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><ul><li><strong>完了アラートを表示</strong>: 長時間の操作が終了したときに通知する</li><li><strong>エラーアラートを表示</strong>: 操作が失敗したときに通知を表示する</li><li><strong>サウンド</strong>: 操作完了時にサウンドを再生する</li></ul><h2 id="一般設定-1" tabindex="-1">一般設定 <a class="header-anchor" href="#一般設定-1" aria-label="Permalink to &quot;一般設定&quot;">​</a></h2><p>以下は <strong>設定 → 一般</strong> でアクセスします：</p><ul><li><strong>言語</strong>: English、中文、日本語、などを切り替える</li><li><strong>ログイン時の起動</strong>: ログイン時に NueZip が自動的に起動する</li><li><strong>テーマ</strong>: ライトまたはダークモード（デフォルトはシステムに追従）</li><li><strong>メニューバーアイコン</strong>: メニューバーアイコンを表示または非表示にする</li></ul><h2 id="ヒント" tabindex="-1">ヒント <a class="header-anchor" href="#ヒント" aria-label="Permalink to &quot;ヒント&quot;">​</a></h2><ul><li>お気に入りの圧縮デフォルトを一度設定し、日常のアーカイブ作業を高速化する</li><li>「ログイン時の起動」を有効にして、NueZip を常にワンクリックで呼び出せるようにする</li><li>Finder 機能拡張を使用して、最速の展開／圧縮ワークフローを実現する</li><li>定期的にシステム設定でフォルダアクセスを見直し、整理された状態を保つ</li></ul>',31)])])}const p=r(o,[["render",n]]);export{c as __pageData,p as default};
